      try {
        pkStr = JSON.stringify(credential.publicKey).substring(0, 100);
      } catch (e2) {
        pkStr = String(credential.publicKey);
      }
      const debugInfo = `len=${credential.publicKey?.length}, type=${typeof credential.publicKey}, val=${pkStr}`;
