// src/features/vault/vaultRoutes.ts
var vault5 = new Hono2();
var getService2 = (c2) => {
  const repo = new VaultRepository(c2.env.DB);
  return new VaultService(c2.env, repo);
};
var getTrashService = (c2) => {
  const repo = new VaultRepository(c2.env.DB);
  return new TrashService(c2.env, repo);
};
var getByosSyncService = (c2) => {
  const repo = new VaultRepository(c2.env.DB);
  return new ByosSyncService(c2.env, repo);
};
vault5.use("/*", authMiddleware);
vault5.get("/", async (c2) => {
  const page = parseInt(c2.req.query("page") || "1", 10);
  const limit = parseInt(c2.req.query("limit") || "12", 10);
  const search = c2.req.query("search") || "";
  const category = c2.req.query("category") || "";
  const user = c2.get("user");
  const service = getService2(c2);
  const result = await service.getAccountsPaginated(user.email || user.id, page, limit, search, category);
  return c2.json({
    success: true,
    hasDecryptionError: result.hasDecryptionError,
    vault: result.items,
    categoryStats: result.categoryStats,
    trashCount: result.trashCount,
    pagination: {
      page,
      limit,
      totalItems: result.totalCount,
      totalPages: result.totalPages
    }
  });
});
vault5.post("/reorder", async (c2) => {
  const { ids } = await c2.req.json();
  if (!Array.isArray(ids)) {
    return c2.json({ success: false, error: "ids must be an array" }, 400);
  }
  const service = getService2(c2);
  await service.reorderAccounts(ids);
  return c2.json({ success: true });
});
vault5.patch("/:id/sort-order", async (c2) => {
  const id = c2.req.param("id");
  const { sortOrder } = await c2.req.json();
  if (typeof sortOrder !== "number") {
    return c2.json({ success: false, error: "sortOrder must be a number" }, 400);
  }
  const service = getService2(c2);
  await service.moveSingleItem(id, sortOrder);
  return c2.json({ success: true });
});
vault5.get("/trash", async (c2) => {
  const trashService = getTrashService(c2);
  const vault6 = await trashService.getTrashList();
  return c2.json({ success: true, vault: vault6 });
});
vault5.post("/:id/trash_move", async (c2) => {
  const id = c2.req.param("id");
  const trashService = getTrashService(c2);
  const result = await trashService.moveToTrash(id);
  return c2.json(result);
});
vault5.post("/:id/trash_restore", async (c2) => {
  const id = c2.req.param("id");
  const trashService = getTrashService(c2);
  const result = await trashService.restoreItem(id);
  return c2.json(result);
});
vault5.post("/trash_batch_move", async (c2) => {
  const { ids } = await c2.req.json();
  const trashService = getTrashService(c2);
  const result = await trashService.batchMoveToTrash(ids || []);
  return c2.json(result);
});
vault5.delete("/:id/trash_hard", async (c2) => {
  const id = c2.req.param("id");
  const trashService = getTrashService(c2);
  const result = await trashService.hardDelete(id);
  return c2.json(result);
});
vault5.delete("/trash_empty", async (c2) => {
  const trashService = getTrashService(c2);
  const result = await trashService.emptyTrash();
  return c2.json(result);
});
vault5.post("/", async (c2) => {
  const user = c2.get("user");
  const data = await c2.req.json();
  const service = getService2(c2);
  const item = await service.createAccount(user.email || user.id, data);
  return c2.json({ success: true, item });
});
vault5.put("/:id", async (c2) => {
  const id = c2.req.param("id");
  const data = await c2.req.json();
  const user = c2.get("user");
  const service = getService2(c2);
  const item = await service.updateAccount(user.email || user.id, id, data);
  return c2.json({ success: true, item });
});
vault5.delete("/:id", async (c2) => {
  const id = c2.req.param("id");
  const service = getService2(c2);
  await service.deleteAccount(id);
  return c2.json({ success: true, message: "Deleted successfully" });
});
vault5.patch("/:id/increment", async (c2) => {
  const id = c2.req.param("id");
  const body = await c2.req.json().catch(() => ({}));
  const service = getService2(c2);
  try {
    const result = await service.incrementCounter(id, body.updatedAt);
    return c2.json({ success: true, ...result });
  } catch (e2) {
    return c2.json({ success: false, error: e2.message }, e2.statusCode || 500);
  }
});
vault5.post("/batch-delete", async (c2) => {
  const { ids } = await c2.req.json();
  if (!Array.isArray(ids) || ids.length === 0) {
    return c2.json({ success: false, error: "ids must be a non-empty array" }, 400);
  }
  const service = getService2(c2);
  const result = await service.batchDeleteAccounts(ids);
  return c2.json({ success: true, count: result.count });
});
vault5.post("/import", rateLimit({
  windowMs: 60 * 1e3,
  max: 5
}), async (c2) => {
  const user = c2.get("user");
  const service = getService2(c2);
  const { content, type, password } = await c2.req.json();
  try {
    const result = await service.importAccounts(user.email || user.id, type, content, password);
    return c2.json({ success: true, ...result });
  } catch (e2) {
    if (e2?.name === "NotSupportedError" || e2?.message?.includes("algorithm") || e2?.message?.includes("not yet supported")) {
      return c2.json({ success: false, error: "import_crypto_not_supported", message: "encrypted_import_requires_pbkdf2_not_available_on_this_platform" }, 422);
    }
    throw e2;
  }
});
vault5.post("/import/blizzard-net", rateLimit({
  windowMs: 60 * 1e3,
  max: 5
}), async (c2) => {
  const { serial: serial3, restoreCode, ssoToken } = await c2.req.json();
  if (!serial3 || !restoreCode) {
    return c2.json({ success: false, error: "serial_and_restore_code_required" }, 400);
  }
  const service = getService2(c2);
  try {
    const secret = await service.restoreBlizzardNetAccount(serial3, restoreCode, ssoToken);
    return c2.json({ success: true, secret });
  } catch (e2) {
    return c2.json({ success: false, error: e2.message }, e2.statusCode || 500);
  }
});
vault5.post("/sync", async (c2) => {
  const user = c2.get("user");
  const { actions } = await c2.req.json();
  if (!Array.isArray(actions)) {
    return c2.json({ success: false, error: "actions must be an array" }, 400);
  }
  const service = getService2(c2);
  const results = await service.batchSync(user.email || user.id, actions);
  return c2.json({ success: true, results });
});
vault5.post("/byos-sync", async (c2) => {
  const user = c2.get("user");
  const body = await c2.req.json();
  const actions = Array.isArray(body?.actions) ? body.actions : [];
  const since = typeof body?.since === "number" ? body.since : 0;
  const offsetUpdates = typeof body?.offsetUpdates === "number" ? body.offsetUpdates : 0;
  const offsetPurged = typeof body?.offsetPurged === "number" ? body.offsetPurged : 0;
  const skipPull = body?.skipPull === true;
  const syncService = getByosSyncService(c2);
  const responseData = await syncService.batchSync(user.email || user.id, actions, since, offsetUpdates, offsetPurged, skipPull);
  return c2.json({
    success: true,
    results: responseData.results,
    updates: responseData.updates,
    purgedIds: responseData.purgedIds,
    serverTime: responseData.serverTime,
    hasMore: responseData.hasMore
  });
});
vault5.post("/migrate-crypto", async (c2) => {
  return c2.json({ success: true, message: "\u4E0D\u518D\u652F\u6301\u65E7\u7248\u76D0\u503C\u8FC1\u79FB\u903B\u8F91\uFF0C\u6240\u6709\u6570\u636E\u9ED8\u8BA4\u5DF2\u4F7F\u7528\u65B0\u7248\u903B\u8F91", migrated: 0, remaining: 0 });
});
var vaultRoutes_default = vault5;

// src/shared/db/repositories/backupRepository.ts
var BackupRepository = class {
  db;
  constructor(dbClient) {
    this.db = dbClient;
  }
  /**
   * 获取所有启用的备份提供商配置 (按名称排序)
   */
  async findAllSettings() {
    return await this.db.select().from(backupProviders4).orderBy(desc(backupProviders4.updatedAt));
  }
  /**
   * 根据提供商类型获取配置
   */
  async findByType(type) {
    const result = await this.db.select().from(backupProviders4).where(eq(backupProviders4.type, type)).limit(1);
    return result[0];
  }
  /**
   * 保存或更新某个提供商的配置
   */
  async upsert(type, data) {
    const existing = await this.findByType(type);
    if (existing) {
      await this.db.update(backupProviders4).set({ ...data, updatedAt: Date.now() }).where(eq(backupProviders4.type, type));
      const result = await this.findByType(type);
      return result;
    } else {
      const insertData = {
        type,
        name: data.name || type.toUpperCase(),
        config: data.config || "{}",
        isEnabled: data.isEnabled ?? true,
        autoBackup: data.autoBackup ?? false,
        autoBackupPassword: data.autoBackupPassword || null,
        createdAt: Date.now(),
        updatedAt: Date.now()
      };
      await this.db.insert(backupProviders4).values(insertData);
      const result = await this.findByType(type);
      return result;
    }
  }
};

